def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))

    token_re = re.compile(r"\s*(\d+|[A-Z]+[1-9]\d?|[A-Z]+|<>|<=|>=|[+\-*/(),:=<>])")
    parsed = {}
    values = {}
    active = set()

    def parse(content):
        tokens = token_re.findall(content[1:])
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = (op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = (op, node, unary())
            return node

        def unary():
            nonlocal pos
            count = 0
            while tokens[pos] == "-":
                count += 1
                pos += 1
            node = atom()
            return ("neg", node) if count % 2 else node

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token.isdigit():
                return ("int", int(token))
            if token == "(":
                node = expression()
                pos += 1
                return node
            if token in ("SUM", "MIN", "MAX"):
                pos += 1
                args = []
                while True:
                    if (
                        pos + 1 < len(tokens)
                        and re.fullmatch(r"[A-Z][1-9]\d?", tokens[pos])
                        and tokens[pos + 1] == ":"
                    ):
                        args.append(("range", tokens[pos], tokens[pos + 2]))
                        pos += 3
                    else:
                        args.append(expression())
                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1
                return ("func", token, args)
            if token == "IF":
                pos += 1
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1
                then = expression()
                pos += 1
                otherwise = expression()
                pos += 1
                return ("if", op, left, right, then, otherwise)
            return ("cell", token)

        return expression()

    def cell_value(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return "#CYCLE!"

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            if name not in parsed:
                parsed[name] = parse(content)
            result = evaluate(parsed[name])
        else:
            result = int(content)
        active.remove(name)
        values[name] = result
        return result

    def evaluate(node):
        kind = node[0]

        if kind == "int":
            return node[1]
        if kind == "cell":
            return cell_value(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value

        if kind in ("+", "-", "*", "/"):
            left = evaluate(node[1])
            if isinstance(left, str):
                return left
            right = evaluate(node[2])
            if isinstance(right, str):
                return right
            if kind == "+":
                return left + right
            if kind == "-":
                return left - right
            if kind == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "if":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(node[4] if condition else node[5])

        function = node[1]
        result = 0
        has_value = False
        for arg in node[2]:
            if arg[0] == "range":
                first, last = arg[1], arg[2]
                col1, col2 = sorted((ord(first[0]), ord(last[0])))
                row1, row2 = sorted((int(first[1:]), int(last[1:])))
                items = (
                    chr(col) + str(row)
                    for row in range(row1, row2 + 1)
                    for col in range(col1, col2 + 1)
                    if chr(col) + str(row) in cells
                )
                for name in items:
                    value = cell_value(name)
                    if isinstance(value, str):
                        return value
                    if function == "SUM":
                        result += value
                    elif not has_value:
                        result = value
                    elif function == "MIN":
                        result = min(result, value)
                    else:
                        result = max(result, value)
                    has_value = True
            else:
                value = evaluate(arg)
                if isinstance(value, str):
                    return value
                if function == "SUM":
                    result += value
                elif not has_value:
                    result = value
                elif function == "MIN":
                    result = min(result, value)
                else:
                    result = max(result, value)
                has_value = True
        return result

    return {name: cell_value(name) for name in cells}
